def pre_suggestion_proposal(source):
    from suggestion_task_scope_contract import pre_suggestion_task
    source = pre_suggestion_task(source)
    for _, old, new, count in reversed(CHANGES):
        if new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source

def pre_suggestion_proposal_bytes(path):
    data = path.read_bytes()
    return pre_suggestion_proposal(data.decode()).encode() if path.suffix == '.swift' else data

