def pre_suggestion_proposal_history_bytes(path):
    from suggestion_task_scope_contract import pre_suggestion_task_history_bytes
    data = pre_suggestion_task_history_bytes(path)
    if path.suffix == ".swift":
        data = pre_suggestion_proposal(data.decode()).encode()
    if path.suffix != '.py':
        return data
    source = data.decode()
    for changed, old, new, count in reversed(HISTORICAL_TEST_CHANGES):
        if (path.as_posix() == changed or path.as_posix().endswith('/' + changed)) and new in source:
            assert source.count(new) == count
            source = source.replace(new, old)
    return source.encode()
